function test_pll_setup_sweeps()
% Generated by GitHub Copilot under Lance Lascari's direction.
% Offline sweep controls/generation tests with isolated output and GUI state.
tool_directory=fileparts(mfilename('fullpath'));
path_before=path;
directory_before=pwd;
visibility_before=get(0,'defaultfigurevisible');
temporary=tempname();
mkdir(temporary);
cleanup=onCleanup(@() cleanup_test(temporary,path_before,directory_before,visibility_before));
addpath(tool_directory,fullfile(tool_directory,'..','pn'));
set(0,'defaultfigurevisible','off');
if exist('OCTAVE_VERSION','builtin')
    graphics_toolkit('qt');
end
types={'List','Start / stop / step','Log (points per octave)'};
assert(isequal(rfdude_pll_sweep_values(types{1},'[500:600:2000]','','','',''),[500 1100 1700]));
assert(isequal(rfdude_pll_sweep_values(types{2},'unused','500','2000','600','unused'),[500 1100 1700]));
assert(isequal(rfdude_pll_sweep_values(types{2},'','4','2','-1',''),[4 3 2]));
assert(isequal(rfdude_pll_sweep_values(types{2},'','2','2','1',''),2));
values=rfdude_pll_sweep_values(types{3},'unused','1000','4000','unused','2');
expected=1000*2.^((0:4)/2);
assert(isrow(values) && numel(values)==5);
assert(max(abs(values-expected))<1e-10);
assert(values(1)==1000 && values(end)==4000);
values=rfdude_pll_sweep_values(types{3},'','4000','1000','','2');
assert(max(abs(values-fliplr(expected)))<1e-10);
values=rfdude_pll_sweep_values(types{3},'','1000','3000','','2');
assert(max(abs(values-[expected(1:4) 3000]))<1e-10);
values=rfdude_pll_sweep_values(types{3},'','3000','1000','','1');
assert(max(abs(values-[3000 1500 1000]))<1e-10);
assert(isequal(rfdude_pll_sweep_values(types{3},'','2','2','','2'),2));
assert(isequal(rfdude_pll_sweep_values(types{3},'','1',num2str(1+eps,17),'','4'),[1 1+eps]));
values=rfdude_pll_sweep_values(types{3},'','1e-200','1e200','','1');
assert(isrow(values) && values(1)==1e-200 && values(end)==1e200 && all(diff(values)>0));
assert(numel(rfdude_pll_sweep_values(types{2},'','1','100000','1',''))==100000);
assert(numel(rfdude_pll_sweep_values(types{3},'','1','2','','99999'))==100000);
must_fail(@() rfdude_pll_sweep_values(types{1},'[1 1]','','','',''));
must_fail(@() rfdude_pll_sweep_values(types{1},'Inf','','','',''));
must_fail(@() rfdude_pll_sweep_values(types{2},'','1','4','0',''));
must_fail(@() rfdude_pll_sweep_values(types{2},'','1','4','-1',''));
must_fail(@() rfdude_pll_sweep_values(types{2},'','[1 2]','4','1',''));
must_fail(@() rfdude_pll_sweep_values(types{2},'','1','100001','1',''));
must_fail(@() rfdude_pll_sweep_values(types{3},'','0','4','','2'));
must_fail(@() rfdude_pll_sweep_values(types{3},'','1','-4','','2'));
must_fail(@() rfdude_pll_sweep_values(types{3},'','1','4','','0'));
must_fail(@() rfdude_pll_sweep_values(types{3},'','1','4','','1.5'));
must_fail(@() rfdude_pll_sweep_values(types{3},'','1','2','','100000'));
must_fail(@() rfdude_pll_sweep_values(types{3},'','1','3','','70000'));
must_fail(@() rfdude_pll_sweep_values('unsupported','','','','',''));

% Each GUI mode resolves to an ordinary vector in a runnable saved script.
config=rfdude_pll_configuration();
config.pll_inputs_s.bSaveFigs=0;
config.pll_inputs_s.bWriteCSVtable=0;
config.pll_inputs_s.bDoTransient=0;
config.pll_inputs_s.bDoTransientNonlinear=0;
config.pll_inputs_s.fsweep_main_pts=101;
config.run_options_s.bRunSweep=true;
config.run_options_s.bShowCorePlots=false;
config.run_options_s.bEnableDataViewer=false;
for mode=1:3
    config.run_options_s.sweep_values=rfdude_pll_sweep_values(types{mode}, ...
        '[1000 2000 4000]','1000','4000','1500','1');
    config.pll_inputs_s.def_filename=sprintf('_sweep_type%d.mat',mode);
    filename=fullfile(temporary,sprintf('aa_run_sweep_type%d.m',mode));
    rfdude_pll_generate_script(config,filename);
    data=execute_script(filename);
    assert(all(data.completed));
    assert(isequal(data.values,config.run_options_s.sweep_values));
    assert(numel(data.cases)==3);
    for k=1:numel(data.values)
        assert(data.cases{k}.requested_inputs.BW_desired_Hz==data.values(k));
    end
end

% Suppressed sweeps create no core figures/exports and leave numbers unchanged.
config.run_options_s.sweep_values=[1000 4000];
config.run_options_s.bShowCorePlots=true;
config.pll_inputs_s.bSaveFigs=1;
config.pll_inputs_s.bSaveFigsJPG=1;
config.pll_inputs_s.bDoTransient=1;
config.pll_inputs_s.bDoTransientNonlinear=1;
config.pll_inputs_s.transient_tmax_s=.001;
config.pll_inputs_s.transient_points=301;
config.pll_inputs_s.transient_nl_steps_per_ref=10;
config.run_options_s.base_directory=temporary;
config.pll_inputs_s.def_filename='_plotted.mat';
config.run_options_s.bSuppressSweepPlots=false;
plotted=rfdude_pll_run(config.pll_inputs_s,config.run_options_s);
assert(numel(dir(fullfile(temporary,'_plotted_cases','*.jpg')))==12);
close all;
config.pll_inputs_s.def_filename='_suppressed.mat';
config.run_options_s.bSuppressSweepPlots=true;
figures_before=numel(findall(0,'type','figure'));
suppressed=rfdude_pll_run(config.pll_inputs_s,config.run_options_s);
assert(all(suppressed.completed));
assert(isempty(dir(fullfile(temporary,'_suppressed_cases','*.jpg'))));
assert(numel(findall(0,'type','figure'))==figures_before);
for k=1:2
    a=plotted.cases{k};
    b=suppressed.cases{k};
    assert(isequal(a.pn_struct.n,b.pn_struct.n) && isequal(a.components,b.components));
    assert(isequal(a.small_signal.frequency_error_Hz,b.small_signal.frequency_error_Hz));
    assert(isequal(a.nonlinear.frequency_error_Hz,b.nonlinear.frequency_error_Hz));
    assert(b.effective_inputs.bCorePlots==0 && a.effective_inputs.bCorePlots==1);
end

state_file=fullfile(temporary,'_last_setup.mat');
gui=bb_pll_setup_gui(state_file);
type_control=findobj(gui,'tag','o_sweep_type');
assert(isequal(get(type_control,'string'),types.'));
assert(get(type_control,'value')==1 && strcmp(get(type_control,'enable'),'off'));
set(findobj(gui,'tag','pll_setup_section'),'value',7);
sweep=findobj(gui,'tag','o_bRunSweep');
set(sweep,'value',1);
invoke(sweep);
assert(strcmp(get(type_control,'enable'),'on'));
list=findobj(gui,'tag','o_sweep_values');
first=findobj(gui,'tag','o_sweep_start');
last=findobj(gui,'tag','o_sweep_stop');
step=findobj(gui,'tag','o_sweep_step');
points=findobj(gui,'tag','o_sweep_points_per_octave');
set(list,'string','[500:600:2000]');
for mode=1:3
    set(type_control,'value',mode);
    invoke(type_control);
    assert(strcmp(get(list,'visible'),on_off(mode==1)));
    assert(strcmp(get(first,'visible'),on_off(mode~=1)));
    assert(strcmp(get(last,'visible'),on_off(mode~=1)));
    assert(strcmp(get(step,'visible'),on_off(mode==2)));
    assert(strcmp(get(points,'visible'),on_off(mode==3)));
    panel=get(type_control,'parent');
    visible_controls=findobj(panel,'visible','on');
    for k=1:numel(visible_controls)
        if strcmp(get(visible_controls(k),'type'),'uicontrol')
            position=get(visible_controls(k),'position');
            assert(position(2)>=0 && position(2)+position(4)<=1);
        end
    end
end
set(first,'string','unfinished start');
set(last,'string','3000');
set(step,'string','600');
set(points,'string','2');
invoke(first);
set(sweep,'value',0);
invoke(sweep);
assert(strcmp(get(points,'enable'),'off'));
close(gui);
gui=bb_pll_setup_gui(state_file);
assert(get(findobj(gui,'tag','o_sweep_type'),'value')==3);
assert(strcmp(get(findobj(gui,'tag','o_sweep_values'),'string'),'[500:600:2000]'));
assert(strcmp(get(findobj(gui,'tag','o_sweep_start'),'string'),'unfinished start'));
assert(strcmp(get(findobj(gui,'tag','o_sweep_stop'),'string'),'3000'));
assert(strcmp(get(findobj(gui,'tag','o_sweep_step'),'string'),'600'));
assert(strcmp(get(findobj(gui,'tag','o_sweep_points_per_octave'),'string'),'2'));
assert(get(findobj(gui,'tag','pll_setup_section'),'value')==7);
delete(gui);

% Older state files have only the list; new fields must not discard it.
stored=load(state_file,'last');
last=stored.last;
last.raw=rmfield(last.raw,{'o_sweep_type','o_sweep_start','o_sweep_stop', ...
    'o_sweep_step','o_sweep_points_per_octave'});
save(state_file,'last','-v7');
gui=bb_pll_setup_gui(state_file);
assert(get(findobj(gui,'tag','o_sweep_type'),'value')==1);
assert(strcmp(get(findobj(gui,'tag','o_sweep_values'),'string'),'[500:600:2000]'));
assert(strcmp(get(findobj(gui,'tag','o_sweep_values'),'visible'),'on'));
delete(gui);
fprintf('\nPASS: list/linear/log vectors, endpoints, limits, generated runs, GUI mode switching and legacy persistence\n');
end

function invoke(control)
callback=get(control,'callback');
callback(control,[]);
end

function state=on_off(yes)
state='off';
if yes
    state='on';
end
end

function data=execute_script(filename)
run(filename);
data=PLL_DATA_s;
end

function must_fail(action)
failed=false;
try
    action();
catch
    failed=true;
end
assert(failed,'Expected an explicit error');
end

function cleanup_test(directory,old_path,old_directory,visibility)
close all;
cd(old_directory);
path(old_path);
set(0,'defaultfigurevisible',visibility);
rmdir(directory,'s');
end
